class Element{constructor(tag){this.tagName=tag.toUpperCase();this.childNodes=[];this.dataset={};this.attrs={};this.value='';this.checked=false;this.disabled=false;this._text='';}append(...xs){for(const x of xs){x.parentNode=this;this.childNodes.push(x);}}replaceChildren(...xs){this.replacements=(this.replacements??0)+1;for(const x of this.childNodes)x.parentNode=null;this.childNodes=[];this._text='';this.append(...xs);}remove(){if(this.parentNode)this.parentNode.childNodes=this.parentNode.childNodes.filter(x=>x!==this);}set textContent(s){this.replaceChildren();this._text=String(s);}get textContent(){return this._text+this.childNodes.map(x=>x.textContent).join('');}setAttribute(k,v){this.attrs[k]=String(v);}getAttribute(k){return this.attrs[k]??null;}}
Element.prototype.querySelectorAll=function(s){return all(this,n=>s.split(',').some(sel=>sel[0]==='.'?(n.className??'').split(' ').includes(sel.slice(1)):sel.startsWith('[data-action=')?n.dataset.action===sel.slice(14,-2):sel.startsWith('[data-part=')?n.dataset.part===sel.slice(12,-2):n.tagName===sel.toUpperCase()));};Element.prototype.querySelector=function(s){return this.querySelectorAll(s)[0]??null;};Element.prototype.contains=function(n){for(let p=n;p;p=p.parentNode)if(p===this)return true;return false;};Element.prototype.focus=function(){document.activeElement=this;};Element.prototype.addEventListener=function(k,f){(this.handlers??={})[k]=f;};Element.prototype.removeEventListener=function(k){delete this.handlers?.[k];};Object.defineProperty(Element.prototype,'parentElement',{get(){return this.parentNode??null;}});

const all=(e,f)=>[...(f(e)?[e]:[]),...e.childNodes.flatMap(x=>all(x,f))],action=(h,a)=>all(h,e=>e.dataset.action===a)[0],field=(h,n)=>all(h,e=>e.name===n)[0],flush=()=>new Promise(r=>setImmediate(r));
const P={actorId:'pm_11111111-1111-4111-8111-111111111111',displayName:'ComBba',appearanceId:'00-jolly',revision:1},K={id:'pak_11111111-1111-4111-8111-111111111111',actorId:P.actorId,signerKind:'server_custodial',grantVersion:1,createdAt:100,revokedAt:null};
const view=(state='viewing',reason='setup_required')=>({state,actor:{id:P.actorId,displayName:P.displayName,appearanceId:P.appearanceId,profileRevision:P.revision},attempt:null,receipt:null,reason});
const status=(extra={})=>({connection:{connected:false,lastSeenAt:null},profile:P,authority:{actorId:P.actorId,version:1,active:true,scopes:['world_entry','walk_and_greet']},keys:[K],entry:view(),...extra});
const reply=(body,code=200)=>({ok:code>=200&&code<300,status:code,json:async()=>structuredClone(body)});
function setup(handler=()=>reply(status()),extra={},guided=false){const events=new Map();globalThis.document={createElement:t=>new Element(t),visibilityState:'visible',addEventListener(k,f){events.set(k,f);},removeEventListener(k,f){if(events.get(k)===f)events.delete(k);}};const host=new Element('main'),calls=[],copies=[],changes=[],locks=[];let sequence=0,clock=1000;const timers=new Map();let id=0;
 const c=mountPersonalConnection(host,{fetcher:async(url,init)=>{calls.push({url,...init});return handler(url,init);},getWorldId:()=> 'world',confirmChange:()=>true,clipboard:{writeText:async x=>{copies.push(x);}},newOperationId:()=>`op-${++sequence}`,now:()=>clock,setTimer:f=>{timers.set(++id,f);return id;},clearTimer:n=>timers.delete(n),onEntry:e=>changes.push(e),onWriteBusy:b=>locks.push(b),...extra});
 return{host,c,calls,copies,changes,locks,timers,events,async sync(){await c.syncProfile({authenticated:true,profile:P,busy:false});if(!guided)c.setManage(true);},async tick(){clock+=5000;const work=[...timers.values()];timers.clear();for(const f of work)f();await flush();},hide(){document.visibilityState='hidden';events.get('visibilitychange')?.();}};}
async function click(t,a){const b=action(t.host,a);assert.ok(b,a+' exists');await b.onclick();await flush();}
test('mount and profile sync never grant, issue, attempt or copy automatically',async()=>{const t=setup();assert.equal(t.calls.length,0);await t.sync();assert.ok(t.calls.length===1&&t.calls[0].url==='/api/personal/status');assert.ok(t.calls.every(x=>x.method==='GET'));assert.equal(t.copies.length,0);t.c.dispose();});
