test('permission POST uses exactly explicitly checked scopes, never adding world_entry',async()=>{let posted;const t=setup((url,init)=>{if(init.method==='GET')return reply(status());posted=JSON.parse(init.body);return reply({authority:{actorId:P.actorId,version:2,active:true,scopes:posted.scopes}});});await t.sync();for(const x of all(t.host,e=>e.type==='checkbox'))x.checked=false;await click(t,'grant');assert.equal(posted,undefined);field(t.host,'scope-walk_and_greet').checked=true;await click(t,'grant');assert.deepEqual(posted,{expectedVersion:1,scopes:['walk_and_greet']});t.c.dispose();});
test('raw key is password-only, omitted from safe state/setup and copied only by its explicit button',async()=>{const raw='msly_'+'A'.repeat(43),t=setup((_u,init)=>init.method==='GET'?reply(status()):reply({status:'issued',key:raw,row:K}));await t.sync();await click(t,'issue-key');const input=field(t.host,'one-time-key');assert.equal(input.type,'password');assert.equal(input.value,raw);assert.equal(JSON.stringify(t.c.state()).includes(raw),false);assert.equal(t.host.textContent.includes(raw),false);assert.equal(t.copies.length,0);await click(t,'copy-key');assert.deepEqual(t.copies,[raw]);t.c.setVisible(false);assert.equal(input.value,'');assert.equal(field(t.host,'one-time-key'),undefined);t.c.dispose();});
