test('poll does not supersede a pending write and stops on hidden/dispose',async()=>{let resolve;const held=new Promise(r=>resolve=r),t=setup((_u,init)=>init.method==='GET'?reply(status()):held);await t.sync();const p=action(t.host,'issue-key').onclick();await flush();const n=t.calls.length;await t.tick();await t.c.refresh();assert.equal(t.calls.length,n);t.hide();resolve(reply({status:'already_issued',row:K}));await p;assert.equal(t.timers.size,0);t.c.dispose();assert.equal(t.events.size,0);});
test('attempt takes actual world, key and CAS revisions; setup has register_agent and signed enter_world but no raw key',async()=>{let posted;const t=setup((_u,init)=>{if(init.method==='GET')return reply(status());posted=JSON.parse(init.body);const attempt={id:'pea_11111111-1111-4111-8111-111111111111',actorId:P.actorId,keyId:K.id,grantVersion:1,profileRevision:1,worldId:'world',scopeHash:'75a27b5c8e0369f8440ce477dec2fe2d0c0bdd6513b605e3fb57e90b8d3ee823',createdAt:1000,expiresAt:601000,status:'pending',validity:'pending'};return reply({attempt,entry:{...view('joining','waiting_connector'),attempt:{id:attempt.id,expiresAt:attempt.expiresAt,status:'pending'}}});});await t.sync();await click(t,'create-attempt');assert.deepEqual(posted,{operationId:'op-1',keyId:K.id,expectedGrantVersion:1,expectedProfileRevision:1,worldId:'world'});const text=field(t.host,'connector-setup').value;assert.match(text,/register_agent/);assert.match(text,/enter_world/);assert.match(text,/pea_/);assert.doesNotMatch(text,/msly_/);assert.equal(t.c.state().entry.state,'joining');t.c.dispose();});
