test('virtual location remains unset until explicit selection and describes existing travel/token cost',async()=>{const presets=[['hq','HQ commons'],['stanford','Stanford'],['san-francisco','San Francisco'],['oakland','Oakland'],['san-mateo','San Mateo'],['mountain-view','Mountain View'],['redwood-city','Redwood City'],['san-jose','San Jose']].map(([id,label])=>({id,label}));let posted;const t=setup((u,i)=>{if(u==='/api/personal/status')return reply(status());if(i.method==='GET')return reply({location:null,presets});posted=JSON.parse(i.body);return reply({location:{source:'virtual',preset:'hq',area:'hq',cell:'3745:-12216',target:'commons:hq',verified:false,setAt:1000,muse:P.actorId},presets,follow:null});});await t.sync();await click(t,'load-location');assert.equal(field(t.host,'virtual-preset').value,'');assert.equal(t.calls.filter(x=>x.method==='POST').length,0);assert.match(t.host.textContent,/TaxiToken/);field(t.host,'virtual-preset').value='hq';await click(t,'save-location');assert.deepEqual(posted,{source:'virtual',preset:'hq',verify:false});assert.match(t.host.textContent,/draft|entry itself/i);t.c.dispose();});
