test('normal fractional follow ETA is accepted while nonfinite or negative ETA stays invalid',async()=>{const presets=[['hq','HQ commons'],['stanford','Stanford'],['san-francisco','San Francisco'],['oakland','Oakland'],['san-mateo','San Mateo'],['mountain-view','Mountain View'],['redwood-city','Redwood City'],['san-jose','San Jose']].map(([id,label])=>({id,label}));for(const etaMs of[0.25,123.125,NaN,Infinity,-1]){const t=setup((u,i)=>u==='/api/personal/status'?reply(status()):i.method==='GET'?reply({location:null,presets}):reply({location:{source:'virtual',preset:'hq',area:'hq',cell:'3745:-12216',target:'commons:hq',verified:false,setAt:1000,muse:P.actorId},presets,follow:{mode:'walking',etaMs}}));await t.sync();await click(t,'load-location');field(t.host,'virtual-preset').value='hq';await click(t,'save-location');assert.equal(t.c.state().phase,Number.isFinite(etaMs)&&etaMs>=0?'ready':'error');t.c.dispose();}});
test('late clipboard success or failure for keyA cannot replace the message for new keyB',async()=>{for(const rejects of[false,true]){let release,reject;const held=new Promise((r,j)=>{release=r;reject=j;}),keys=[];let n=0;const t=setup((_u,i)=>{if(i.method==='GET')return reply(status({keys}));const row={...K,id:n++===0?K.id:'pak_22222222-2222-4222-8222-222222222222'};keys.unshift(row);return reply({status:'issued',key:'msly_'+(n===1?'F':'G').repeat(43),row});},{clipboard:{writeText:()=>held}});await t.sync();await click(t,'issue-key');const pending=action(t.host,'copy-key').onclick();await flush();await click(t,'issue-key');const before=t.host.textContent;if(rejects)reject(Error('clipboard'));else release();await pending;assert.equal(t.host.textContent,before);assert.match(t.host.textContent,/shown once/);t.c.dispose();}});
test('cached setup suppresses paused/unavailable and expired instructions, retaining valid joined plus pending',async()=>{for(const scenario of['paused','unavailable','compact-expired','cache-expired','joined']){let clock=1000,created=false,mode='joining',compactExpires=601000;const a={id:'pea_11111111-1111-4111-8111-111111111111',actorId:P.actorId,keyId:K.id,grantVersion:1,profileRevision:1,worldId:'world',scopeHash:'75a27b5c8e0369f8440ce477dec2fe2d0c0bdd6513b605e3fb57e90b8d3ee823',createdAt:1000,expiresAt:601000,status:'pending',validity:'pending'},e=()=>({...view(mode==='joined'?'joined':mode==='paused'||mode==='unavailable'?'error':'joining',mode==='joined'?null:mode==='paused'?'paused':mode==='unavailable'?'unavailable':'waiting_connector'),attempt:{id:a.id,expiresAt:compactExpires,status:'pending'},receipt:mode==='joined'?{id:'current-old-entry',actorId:P.actorId,worldId:'world',committedAt:900}:null});const t=setup((_u,i)=>i.method==='GET'?reply(status(created?{entry:e()}:{})):(created=true,reply({attempt:a,entry:e()})),{now:()=>clock});await t.sync();await click(t,'create-attempt');assert.equal(field(t.host,'connector-setup').value.includes(a.id),true);if(scenario==='cache-expired'){clock=601001;await click(t,'copy-setup');}else{if(scenario==='compact-expired')compactExpires=500;else mode=scenario;await t.c.refresh();}assert.equal((field(t.host,'connector-setup')?.value??'').includes(a.id),scenario==='joined');assert.equal(t.calls.filter(x=>x.method==='POST').length,1);t.c.dispose();}});

test('connection metadata is exact and signed out cannot retain a connection',()=>{assert.deepEqual(parsePersonalStatus(status({connection:{connected:true,lastSeenAt:900}}),P,'world').connection,{connected:true,lastSeenAt:900});for(const connection of[undefined,{connected:true,lastSeenAt:null},{connected:false,lastSeenAt:1},{connected:true,lastSeenAt:-1},{connected:true,lastSeenAt:0},{connected:true,lastSeenAt:1,raw:'CANARY'}])assert.throws(()=>parsePersonalStatus(status({connection}),P,'world'));assert.throws(()=>parsePersonalStatus({profile:null,authority:null,keys:[],entry:{state:'viewing',actor:null,attempt:null,receipt:null,reason:'signed_out'},connection:{connected:true,lastSeenAt:900}},P,'world'));});
test('a first authenticated connector call updates automatically but never becomes world admission',async()=>{let connected=false;const t=setup(()=>reply(status({connection:{connected,lastSeenAt:connected?900:null}})));await t.sync();connected=true;await t.tick();assert.equal(t.c.state().connection.connected,true);assert.equal(t.c.state().entry.state,'viewing');assert.match(t.host.textContent,/Connection confirmed/);assert.match(t.host.textContent,/has not entered the world yet/);assert.ok(t.calls.every(x=>x.method==='GET'));t.c.dispose();});
const outsideAdvanced=e=>{for(let p=e.parentNode;p;p=p.parentNode)if(p.tagName==='DETAILS'&&!p.open)return false;return !e.hidden;};
test('connection setup has three ordered text steps and one current primary action',async()=>{const t=setup();await t.sync();assert.equal(all(t.host,e=>e.className==='entry-setup-steps')[0].childNodes.length,3);assert.match(t.host.textContent,/settings/);assert.match(t.host.textContent,/custom connector/);assert.match(t.host.textContent,/Paste the key/);assert.doesNotMatch(t.host.textContent,/undefined/);assert.equal(all(t.host,e=>e.tagName==='BUTTON'&&e.className==='primary'&&outsideAdvanced(e)).length,1);assert.ok(all(t.host,e=>e.tagName==='DETAILS').length);assert.ok(t.calls.every(x=>x.method==='GET'));t.c.dispose();});

const RECOMMENDED=['world_entry','walk_and_greet','answer_yes_no','world_item_discover'];
const freshStatus=()=>status({authority:{actorId:P.actorId,version:0,active:false,scopes:[]},keys:[]});
test('fresh setup recommends exactly four choices and folds five optional permissions without any automatic write',async()=>{const t=setup(()=>reply(freshStatus()));await t.sync();const fields=all(t.host,x=>x.type==='checkbox');assert.equal(fields.length,9);assert.deepEqual(fields.filter(x=>x.checked).map(x=>x.name.slice(6)).sort(),[...RECOMMENDED].sort());const more=all(t.host,x=>x.className==='entry-more-permissions')[0];assert.equal(Boolean(more.open),false);assert.equal(all(more,x=>x.type==='checkbox').length,5);assert.ok(all(more,x=>x.type==='checkbox').every(x=>!x.checked));assert.equal(all(t.host,x=>x.tagName==='H3').length,1);assert.equal(action(t.host,'grant').textContent,'Allow and continue');assert.ok(t.calls.every(x=>x.method==='GET'));t.c.dispose();});
test('edited recommendations and optional checks survive poll, rerender and folding without being reselected',async()=>{const t=setup(()=>reply(freshStatus()));await t.sync();field(t.host,'scope-world_entry').checked=false;field(t.host,'scope-world_item_gift').checked=true;const more=all(t.host,x=>x.className==='entry-more-permissions')[0];more.open=true;more.ontoggle();await t.c.refresh();assert.equal(field(t.host,'scope-world_entry').checked,false);assert.equal(field(t.host,'scope-world_item_gift').checked,true);assert.equal(all(t.host,x=>x.className==='entry-more-permissions')[0].open,true);t.c.setVisible(false);t.c.setVisible(true);await flush();assert.equal(field(t.host,'scope-world_entry').checked,false);assert.equal(field(t.host,'scope-world_item_gift').checked,true);assert.ok(t.calls.every(x=>x.method==='GET'));t.c.dispose();});
test('existing grants retain their actual choices and never acquire the new defaults',async()=>{const t=setup(()=>reply(status({authority:{actorId:P.actorId,version:4,active:true,scopes:['walk_and_greet','world_item_gift']},keys:[]})));await t.sync();assert.equal(field(t.host,'scope-world_entry').checked,false);assert.equal(field(t.host,'scope-world_item_discover').checked,false);assert.equal(field(t.host,'scope-world_item_gift').checked,true);assert.ok(t.calls.every(x=>x.method==='GET'));t.c.dispose();});
test('Allow and continue sends only one explicit grant, never an automatic key or world-entry command',async()=>{const t=setup((u,i)=>i.method==='GET'?reply(freshStatus()):reply({authority:{actorId:P.actorId,version:1,active:true,scopes:JSON.parse(i.body).scopes}}));await t.sync();assert.equal(t.calls.length,1);await click(t,'grant');const writes=t.calls.filter(x=>x.method!=='GET');assert.equal(writes.length,1);assert.equal(writes[0].url,'/api/personal/authority');assert.deepEqual(JSON.parse(writes[0].body),{expectedVersion:0,scopes:RECOMMENDED});assert.equal(t.c.state().keys.length,0);assert.notEqual(t.c.state().entry.state,'joined');assert.equal(action(t.host,'issue-key').textContent,'Create a new key');t.c.dispose();});

test('public MCP URL copy is distinct from the shown-once Musely key and never mutates authority or entry',async()=>{const raw='msly_'+'H'.repeat(43),t=setup((_u,i)=>i.method==='GET'?reply(status()):reply({status:'issued',key:raw,row:K}));await t.sync();await click(t,'issue-key');const count=t.calls.length;assert.match(t.host.textContent,/Musely connection key · shown once/);assert.match(t.host.textContent,/Paste it into Muse → Settings → Custom connector \(Musely · https:\/\/musely.net\/mcp\) → secure API key field\. Keep it private\./);assert.doesNotMatch(t.host.textContent,/One-time connection key|msly_/);const list=all(t.host,x=>x.className==='entry-setup-steps')[0];assert.equal(list.tagName,'OL');assert.equal(list.childNodes.length,3);assert.match(list.childNodes[0].textContent,/Open Muse settings/);assert.match(list.childNodes[1].textContent,/Add custom connector/);assert.match(list.childNodes[2].textContent,/Paste the key/);await click(t,'copy-mcp-url');assert.deepEqual(t.copies,['https://musely.net/mcp']);assert.equal(t.calls.length,count);assert.equal(field(t.host,'one-time-key').value,raw);await click(t,'copy-key');assert.deepEqual(t.copies,['https://musely.net/mcp',raw]);assert.equal(t.calls.length,count);t.c.dispose();});
test('late public URL clipboard completion cannot reopen a closed key view',async()=>{let resolve;const held=new Promise(r=>resolve=r),t=setup(undefined,{clipboard:{writeText:()=>held}});await t.sync();const pending=action(t.host,'copy-mcp-url').onclick();t.c.setVisible(false);const text=t.host.textContent;resolve();await pending;assert.equal(t.host.textContent,text);assert.equal(t.c.state().rawKeyVisible,false);assert.ok(t.calls.every(x=>x.method==='GET'));t.c.dispose();});

test('six five-second polls preserve actual DOM identities, open menus, choices, focus and panel scroll',async()=>{let seen=1000;const second={...K,id:'pak_22222222-2222-4222-8222-222222222222'},t=setup(()=>reply(status({keys:[K,second],connection:{connected:true,lastSeenAt:++seen}})));await t.sync();const root=t.host.childNodes[0],advanced=all(root,n=>n.className==='entry-advanced')[0],more=all(root,n=>n.className==='entry-more-permissions')[0],key=field(root,'key-id'),scope=field(root,'scope-world_item_gift');advanced.open=true;advanced.ontoggle();more.open=true;more.ontoggle();scope.checked=true;key.focus();key.value=second.id;key.onchange();root.scrollTop=80;t.host.scrollTop=240;const children=[...root.childNodes],changes=all(root,()=>true).reduce((n,x)=>n+(x.replacements??0),0);for(let i=0;i<6;i++)await t.tick();assert.equal(t.calls.length,7);assert.deepEqual(root.childNodes,children);assert.equal(all(root,n=>n.className==='entry-advanced')[0],advanced);assert.equal(advanced.open,true);assert.equal(more.open,true);assert.equal(field(root,'key-id'),key);assert.equal(key.value,second.id);assert.equal(field(root,'scope-world_item_gift'),scope);assert.equal(scope.checked,true);assert.equal(document.activeElement,key);assert.equal(root.scrollTop,80);assert.equal(t.host.scrollTop,240);assert.equal(all(root,()=>true).reduce((n,x)=>n+(x.replacements??0),0),changes);assert.ok(t.calls.every(x=>x.method==='GET'));t.c.dispose();});
test('identical polls while no field is focused never regenerate DOM after checkbox or details changes',async()=>{const t=setup();await t.sync();const root=t.host.childNodes[0],advanced=all(root,n=>n.className==='entry-advanced')[0],scope=field(root,'scope-world_item_gift'),count=root.replacements;advanced.open=true;advanced.ontoggle();scope.checked=true;for(let i=0;i<6;i++)await t.tick();assert.equal(root.replacements,count);assert.equal(field(root,'scope-world_item_gift'),scope);assert.equal(scope.checked,true);assert.equal(advanced.open,true);t.c.dispose();});
test('real status changes patch the status during input then restore the expanded controls and scroll on blur',async()=>{let connected=false;const t=setup(()=>reply(status({connection:{connected,lastSeenAt:connected?1000:null}})));await t.sync();const root=t.host.childNodes[0],advanced=all(root,n=>n.className==='entry-advanced')[0],key=field(root,'key-id');advanced.open=true;advanced.ontoggle();key.focus();t.host.scrollTop=320;const count=root.replacements;connected=true;await t.tick();assert.equal(field(root,'key-id'),key);assert.equal(root.replacements,count);assert.match(root.textContent,/Connection confirmed/);document.activeElement=null;root.handlers.focusout();await flush();assert.equal(all(root,n=>n.className==='entry-advanced')[0].open,true);assert.equal(field(root,'key-id').value,K.id);assert.equal(t.host.scrollTop,320);t.c.dispose();});
test('unavoidable nonsecurity render restores focused action and scroll without copying the raw key',async()=>{const t=setup();await t.sync();const root=t.host.childNodes[0],advanced=all(root,n=>n.className==='entry-advanced')[0];advanced.open=true;advanced.ontoggle();const button=action(root,'copy-mcp-url');button.focus();root.scrollTop=100;t.host.scrollTop=300;await button.onclick();assert.equal(document.activeElement,action(root,'copy-mcp-url'));assert.equal(all(root,n=>n.className==='entry-advanced')[0].open,true);assert.equal(root.scrollTop,100);assert.equal(t.host.scrollTop,300);assert.deepEqual(t.copies,['https://musely.net/mcp']);t.c.dispose();});
for(const ending of['revoke','logout','expired'])test('security '+ending+' bypasses input deferral and clears one-time key immediately',async()=>{let end=false;const raw='msly_'+'J'.repeat(43),t=setup((_u,i)=>{if(i.method!=='GET')return reply({status:'issued',key:raw,row:K});if(end&&(ending==='logout'||ending==='expired'))return reply({error:'ended'},401);return reply(status(end?{keys:[{...K,revokedAt:200}],entry:ending==='expired'?view('viewing','expired'):view()}:{}));});await t.sync();await click(t,'issue-key');const old=field(t.host,'one-time-key');old.focus();t.host.childNodes[0].handlers.pointerdown({target:old});end=true;await t.tick();assert.equal(old.value,'');assert.equal(field(t.host,'one-time-key'),undefined);assert.equal(t.c.state().rawKeyVisible,false);assert.equal(JSON.stringify(t.c.state()).includes(raw),false);t.c.dispose();});
