for(const className of['entry-advanced','entry-more-permissions'])test('a changed live status restores focused '+className+' summary without closing it',async()=>{let connected=false;const t=setup(()=>reply(status({connection:{connected,lastSeenAt:connected?1000:null}})));await t.sync();const root=t.host.childNodes[0],details=all(root,n=>n.className===className)[0];details.open=true;details.ontoggle();details.childNodes[0].focus();t.host.scrollTop=200;connected=true;await t.tick();const current=all(root,n=>n.className===className)[0];assert.equal(current.open,true);assert.equal(document.activeElement,current.childNodes[0]);assert.equal(t.host.scrollTop,200);assert.match(root.textContent,/Connection confirmed/);t.c.dispose();});

for(const operation of['grant','issue-key','create-attempt'])test('foreground '+operation+' interrupts only a background status read and ignores its late401',async()=>{let reads=0,release,issued=false;const writes=[],freshKey={...K,id:'pak_22222222-2222-4222-8222-222222222222'},a={id:'pea_11111111-1111-4111-8111-111111111111',actorId:P.actorId,keyId:K.id,grantVersion:1,profileRevision:1,worldId:'world',scopeHash:'75a27b5c8e0369f8440ce477dec2fe2d0c0bdd6513b605e3fb57e90b8d3ee823',createdAt:1000,expiresAt:601000,status:'pending',validity:'pending'};const t=setup((u,i)=>{if(i.method==='GET'){if(++reads===2)return new Promise(r=>release=r);return reply(status({keys:issued?[freshKey,K]:[K]}));}writes.push({u,...i});if(operation==='grant')return reply({authority:{actorId:P.actorId,version:2,active:true,scopes:JSON.parse(i.body).scopes}});if(operation==='issue-key'){issued=true;return reply({status:'issued',key:'msly_'+'N'.repeat(43),row:freshKey});}return reply({attempt:a,entry:{...view('joining','waiting_connector'),attempt:{id:a.id,status:'pending',expiresAt:a.expiresAt}}});});let pending;try{await t.sync();if(operation==='grant')field(t.host,'scope-world_item_gift').checked=true;await t.tick();pending=t.c.refresh();const oldSignal=t.calls[1].signal;await click(t,operation);assert.equal(writes.length,1,'explicit click must reach its existing API exactly once');assert.equal(oldSignal.aborted,true);assert.equal(JSON.parse(writes[0].body)[operation==='grant'?'expectedVersion':operation==='issue-key'?'expectedVersion':'expectedGrantVersion'],1);release(reply({error:'old_session_expired'},401));await pending;release=null;if(operation==='issue-key')assert.equal(t.c.state().rawKeyVisible,true);assert.equal(t.c.state().phase,'ready');assert.notEqual(t.c.state().entry.reason,'signed_out');assert.equal(writes.length,1);}finally{release?.(reply({error:'old_session_expired'},401));if(pending)await pending;t.c.dispose();}});

for(const operation of['read-attempt','load-location'])test('foreground GET '+operation+' supersedes quiet polling once and keeps foreground read guards',async()=>{let reads=0,releaseQuiet,releaseForeground;const path=operation==='read-attempt'?'/api/personal/entry-attempts/pea_11111111-1111-4111-8111-111111111111':'/api/personal/location',presets=[['hq','HQ commons'],['stanford','Stanford'],['san-francisco','San Francisco'],['oakland','Oakland'],['san-mateo','San Mateo'],['mountain-view','Mountain View'],['redwood-city','Redwood City'],['san-jose','San Jose']].map(([id,label])=>({id,label})),a={id:'pea_11111111-1111-4111-8111-111111111111',actorId:P.actorId,keyId:K.id,grantVersion:1,profileRevision:1,worldId:'world',scopeHash:'75a27b5c8e0369f8440ce477dec2fe2d0c0bdd6513b605e3fb57e90b8d3ee823',createdAt:1000,expiresAt:601000,status:'pending',validity:'pending'},entry={...view('joining','waiting_connector'),attempt:{id:a.id,expiresAt:a.expiresAt,status:'pending'}},answer=operation==='read-attempt'?{attempt:a,entry}:{location:null,presets};const t=setup((u,i)=>{if(u===path)return new Promise(r=>releaseForeground=r);if(u==='/api/personal/status'){if(++reads===2)return new Promise(r=>releaseQuiet=r);return reply(status(operation==='read-attempt'?{entry}:{}));}throw Error('unexpected request');});let pending,explicit;try{await t.sync();await t.tick();pending=t.c.refresh();const oldSignal=t.calls[1].signal,button=action(t.host,operation);explicit=button.onclick();await flush();assert.equal(t.calls.filter(c=>c.url===path).length,1,'explicit GET must run exactly once');assert.equal(oldSignal.aborted,true);await button.onclick();await t.c.refresh();await action(t.host,'issue-key').onclick();assert.equal(t.calls.filter(c=>c.url===path).length,1);assert.equal(t.calls.filter(c=>c.method!=='GET').length,0);releaseQuiet(reply({error:'old_session_expired'},401));await pending;releaseQuiet=null;releaseForeground(reply(answer));await explicit;releaseForeground=null;assert.notEqual(t.c.state().entry.reason,'signed_out');if(operation==='read-attempt')assert.equal(t.c.state().attempt.id,a.id);else assert.equal(field(t.host,'virtual-preset').value,'');}finally{releaseQuiet?.(reply({error:'old_session_expired'},401));if(pending)await pending;releaseForeground?.(reply(answer));if(explicit)await explicit;t.c.dispose();}});

for(const ending of['pointercancel','pointerup'])test('deferred status is applied after '+ending+' without a click or a stuck gesture',async()=>{let connected=false;const t=setup(()=>reply(status({connection:{connected,lastSeenAt:connected?1000:null}})));try{await t.sync();const root=t.host.childNodes[0],select=field(root,'key-id');select.focus();connected=true;await t.tick();const before=root.replacements;root.handlers.pointerdown({target:action(root,'grant')});document.activeElement=null;root.handlers.focusout();await flush();assert.equal(root.replacements,before);t.events.get(ending)();await new Promise(r=>setTimeout(r,1));await flush();assert.ok(root.replacements>before);assert.match(root.textContent,/Connection confirmed/);}finally{t.c.dispose();}assert.equal(t.events.size,0);});

const guidedAction=(t,id)=>action(t.host,id),continueStep=async t=>{await guidedAction(t,'continue').onclick();await flush();};
test('guided steps3–7 write once per explicit action, retain shown-once privacy and distinguish connected from joined',async()=>{
 let authority={actorId:P.actorId,version:0,active:false,scopes:[]},keys=[],entry=view(),connected=false;const raw='msly_'+'Q'.repeat(43),a={id:'pea_11111111-1111-4111-8111-111111111111',actorId:P.actorId,keyId:K.id,grantVersion:1,profileRevision:1,worldId:'world',scopeHash:'75a27b5c8e0369f8440ce477dec2fe2d0c0bdd6513b605e3fb57e90b8d3ee823',createdAt:1000,expiresAt:601000,status:'pending',validity:'pending'};
 const t=setup((u,i)=>{if(u==='/api/personal/status')return reply(status({authority,keys,entry,connection:{connected,lastSeenAt:connected?1000:null}}));if(u==='/api/personal/authority'){authority={...authority,version:1,active:true,scopes:JSON.parse(i.body).scopes};return reply({authority});}if(u==='/api/personal/keys'){keys=[K];return reply({status:'issued',key:raw,row:K});}if(u==='/api/personal/entry-attempts'){entry={...view('joining','waiting_connector'),attempt:{id:a.id,status:'pending',expiresAt:a.expiresAt}};return reply({attempt:a,entry});}throw Error('unexpected fixture request');},{},true);
 try{await t.sync();assert.equal(t.c.state().step,3);assert.equal(all(t.host,n=>n.type==='checkbox'&&n.checked).length,4);assert.equal(action(t.host,'revoke-authority'),undefined);assert.equal(action(t.host,'issue-key'),undefined);await click(t,'grant');assert.equal(t.c.state().step,4);assert.equal(action(t.host,'grant'),undefined);assert.equal(action(t.host,'continue').disabled,true);await click(t,'issue-key');assert.equal(field(t.host,'one-time-key').value,raw);assert.equal(action(t.host,'continue').disabled,true);await click(t,'copy-key');assert.equal(action(t.host,'continue').disabled,false);await continueStep(t);assert.equal(t.c.state().step,5);assert.equal(field(t.host,'one-time-key'),undefined);assert.equal(JSON.stringify(t.c.state()).includes(raw),false);await click(t,'copy-name');await click(t,'copy-mcp-url');assert.deepEqual(t.copies,[raw,'Musely','https://musely.net/mcp']);await continueStep(t);assert.equal(t.c.state().step,6);assert.equal(field(t.host,'key-id').getAttribute('aria-label'),'Key for entry');assert.equal(action(t.host,'continue').disabled,true);await click(t,'create-attempt');assert.equal(field(t.host,'connector-setup').getAttribute('aria-label'),'Instructions for Muse without a key');await click(t,'copy-setup');assert.equal(t.copies.at(-1).includes(a.id),true);assert.equal(t.copies.at(-1).includes(raw),false);connected=true;await t.tick();assert.equal(t.c.state().step,7);assert.match(t.host.textContent,/Your Muse is connected/);assert.doesNotMatch(t.host.textContent,/Your Muse joined the world/);assert.match(t.host.textContent,/5–15 minutes/);await continueStep(t);assert.equal(t.c.state().completed,true);assert.deepEqual(t.calls.filter(c=>c.method==='POST').map(c=>c.url),['/api/personal/authority','/api/personal/keys','/api/personal/entry-attempts']);}finally{t.c.dispose();}
});
test('Manage revoke→allow→new key follows CAS and never exposes unusable keys or invites',async()=>{let a={actorId:P.actorId,version:1,active:true,scopes:['world_entry','walk_and_greet']},keys=[K];const nextKey={...K,id:'pak_22222222-2222-4222-8222-222222222222',grantVersion:3};const t=setup((u,i)=>{if(i.method==='GET')return reply(status({authority:a,keys}));if(i.method==='DELETE'){assert.equal(JSON.parse(i.body).expectedVersion,1);a={...a,version:2,active:false,scopes:[]};return reply({authority:a});}if(u==='/api/personal/authority'){assert.equal(JSON.parse(i.body).expectedVersion,2);a={...a,version:3,active:true,scopes:JSON.parse(i.body).scopes};return reply({authority:a});}assert.equal(JSON.parse(i.body).expectedVersion,3);keys=[nextKey,K];return reply({status:'issued',key:'msly_'+'R'.repeat(43),row:nextKey});});try{await t.sync();await click(t,'revoke-authority');assert.match(t.host.textContent,/Permissions are off. Allow actions again to create a new key./);assert.equal(field(t.host,'key-id'),undefined);assert.equal(action(t.host,'create-attempt'),undefined);assert.ok(action(t.host,'new-key'));const count=t.calls.length;await click(t,'new-key');assert.equal(t.c.state().step,3);assert.equal(t.c.state().manage,false);assert.equal(t.calls.length,count);await click(t,'grant');assert.equal(t.c.state().step,4);await click(t,'issue-key');assert.equal(t.c.state().keys[0].grantVersion,3);assert.equal(t.calls.filter(c=>c.method==='POST'&&c.url.endsWith('/keys')).length,1);}finally{t.c.dispose();}});
for(const mode of['inactive','no-key','key','joined'])test('guided resume derives '+mode+' from exact current server status without writes',async()=>{const e=mode==='joined'?{...view('joined',null),receipt:{id:'current',actorId:P.actorId,worldId:'world',committedAt:900}}:view();const t=setup(()=>reply(status({authority:mode==='inactive'?{actorId:P.actorId,version:8,active:false,scopes:[]}:status().authority,keys:mode==='inactive'||mode==='no-key'?[]:[K],entry:e})),{},true);try{await t.sync();assert.equal(t.c.state().step,mode==='inactive'?3:mode==='no-key'?4:mode==='joined'?7:6);if(mode==='inactive')assert.equal(all(t.host,n=>n.type==='checkbox'&&n.checked).length,4);assert.equal(t.c.state().completed,mode==='joined');assert.ok(t.calls.every(c=>c.method==='GET'));}finally{t.c.dispose();}});
test('ten-minute cap preserves step, DOM, selection, scroll and focus; only explicit reopen/check resumes reads',async()=>{const t=setup(undefined,{},true);try{await t.sync();const root=t.host.childNodes[0],select=field(t.host,'key-id');select.focus();root.scrollTop=180;const children=[...root.childNodes];for(let i=0;i<125;i++)await t.tick();assert.equal(t.c.state().checksPaused,true);assert.equal(t.c.state().step,6);assert.equal(field(t.host,'key-id'),select);assert.equal(root.scrollTop,180);assert.equal(document.activeElement,select);assert.ok(children.every(n=>root.childNodes.includes(n)));const count=t.calls.length;await t.tick();assert.equal(t.calls.length,count);await click(t,'resume-checks');assert.equal(t.calls.length,count+1);assert.equal(t.c.state().checksPaused,false);for(let i=0;i<125;i++)await t.tick();const ended=t.calls.length;t.c.setVisible(false);t.c.setVisible(true);await flush();assert.equal(t.calls.length,ended+1);assert.equal(t.c.state().step,6);assert.equal(t.c.state().rawKeyVisible,false);}finally{t.c.dispose();}});
test('Back and reopen never restore a shown-once key, and late copy cannot acknowledge a cleared value',async()=>{let release,issued=false;const t=setup((u,i)=>i.method==='GET'?reply(status({keys:issued?[K]:[]})):(issued=true,reply({status:'issued',key:'msly_'+'S'.repeat(43),row:K})),{clipboard:{writeText:()=>new Promise(r=>release=r)}},true);try{await t.sync();await click(t,'issue-key');const old=field(t.host,'one-time-key'),pending=action(t.host,'copy-key').onclick();await click(t,'back');assert.equal(old.value,'');assert.equal(t.c.state().step,3);release();await pending;assert.equal(t.c.state().rawKeyVisible,false);t.c.setVisible(false);t.c.setVisible(true);await flush();assert.equal(t.c.state().step,6);assert.equal(field(t.host,'one-time-key'),undefined);assert.equal(t.calls.filter(c=>c.method==='POST').length,1);}finally{t.c.dispose();}});
test('expiry timer still clears private actions after automatic checks have paused',async()=>{const real=globalThis.setTimeout,clear=globalThis.clearTimeout,expiry=new Map();let seq=0,ended=0;globalThis.setTimeout=(f,ms)=>ms===700000?(expiry.set(--seq,f),seq):real(f,ms);globalThis.clearTimeout=id=>expiry.delete(id)||clear(id);const t=setup(undefined,{sessionCurrent:()=>true,sessionExpiresAt:()=>701000,onSessionLost:()=>ended++},true);try{await t.sync();for(let i=0;i<125;i++)await t.tick();assert.equal(t.c.state().checksPaused,true);assert.equal(expiry.size,1);[...expiry.values()][0]();assert.equal(ended,1);assert.equal(t.c.state().keys.length,0);assert.equal(t.c.state().rawKeyVisible,false);assert.equal(action(t.host,'create-attempt'),undefined);assert.equal(t.c.state().entry.reason,'signed_out');}finally{t.c.dispose();globalThis.setTimeout=real;globalThis.clearTimeout=clear;}});


test('stable connected polling respects Back instead of advancing again without a new connection',async()=>{const t=setup(()=>reply(status({connection:{connected:true,lastSeenAt:1000}})),{},true);try{await t.sync();assert.equal(t.c.state().step,7);await click(t,'back');assert.equal(t.c.state().step,6);for(let i=0;i<6;i++)await t.tick();assert.equal(t.c.state().step,6);assert.ok(t.calls.every(c=>c.method==='GET'));}finally{t.c.dispose();}});

// Back through setup must not rotate a permission version or its saved key.
test('same active scope set advances to step4 without writes or entry/key side effects',async()=>{const joined={...view('joined',null),receipt:{id:'current',actorId:P.actorId,worldId:'world',committedAt:900}},t=setup(()=>reply(status({entry:joined})),{},true);try{await t.sync();for(let i=0;i<4;i++)await click(t,'back');assert.equal(t.c.state().step,3);const before=t.c.state(),notifications=t.changes.length;await click(t,'grant');assert.equal(t.calls.filter(c=>c.method!=='GET').length,0);assert.equal(t.c.state().step,4);assert.deepEqual(t.c.state().authority,before.authority);assert.deepEqual(t.c.state().keys,before.keys);assert.deepEqual(t.c.state().entry,before.entry);assert.equal(t.changes.length,notifications);assert.equal(action(t.host,'continue').disabled,false);await continueStep(t);assert.equal(t.c.state().step,5);assert.equal(action(t.host,'continue').disabled,false);}finally{t.c.dispose();}});
for(const accept of[false,true])test('changed active scopes require explicit confirmation '+accept,async()=>{const warnings=[],t=setup((_u,i)=>i.method==='GET'?reply(status()):reply({authority:{actorId:P.actorId,active:true,version:2,scopes:JSON.parse(i.body).scopes}}),{confirmChange:message=>(warnings.push(message),accept)});try{await t.sync();field(t.host,'scope-world_item_gift').checked=true;const before=t.c.state(),notified=t.changes.length;await click(t,'grant');assert.deepEqual(warnings,["Changing permissions turns off your current key. You’ll create a new one."]);assert.equal(t.calls.filter(c=>c.method==='POST').length,accept?1:0);if(!accept){assert.deepEqual(t.c.state(),before);assert.equal(t.changes.length,notified);}else{assert.equal(t.c.state().authority.version,2);assert.equal(JSON.parse(t.calls.at(-1).body).expectedVersion,1);}}finally{t.c.dispose();}});
test('already issued key has an explicit Manage recovery action without automatic revocation or creation',async()=>{const t=setup((_u,i)=>i.method==='GET'?reply(status({keys:[]})):reply({status:'already_issued',row:K}),{},true);try{await t.sync();await click(t,'issue-key');assert.equal(t.c.state().rawKeyVisible,false);assert.equal(action(t.host,'continue').disabled,false);const writes=t.calls.length;await click(t,'recover-key');assert.equal(t.c.state().manage,true);assert.match(t.host.textContent,/Revoke and create a new key/);assert.equal(t.calls.length,writes);assert.ok(action(t.host,'revoke-key-'+K.id));}finally{t.c.dispose();}});

test('same permissions keep a currently shown key and its unsaved-copy acknowledgement gate',async()=>{const t=setup((_u,i)=>i.method==='GET'?reply(status()):reply({status:'issued',key:'msly_'+'Z'.repeat(43),row:K}));try{await t.sync();await click(t,'issue-key');const posts=t.calls.filter(c=>c.method==='POST').length;await click(t,'grant');assert.equal(t.c.state().step,4);assert.equal(t.c.state().rawKeyVisible,true);assert.equal(action(t.host,'continue').disabled,true);assert.equal(t.calls.filter(c=>c.method==='POST').length,posts);await click(t,'saved-key');assert.equal(action(t.host,'continue').disabled,false);}finally{t.c.dispose();}});
test('Korean permission warning is fixed copy and cancel leaves authority and key untouched',async()=>{const storage=globalThis.localStorage;globalThis.localStorage={setItem(){},getItem(){return 'ko';}};setLanguagePreference('ko');let warning;const t=setup(undefined,{confirmChange:text=>(warning=text,false)});try{await t.sync();field(t.host,'scope-world_item_gift').checked=true;await click(t,'grant');assert.equal(warning,'권한을 바꾸면 현재 키를 사용할 수 없어요. 새 키를 만들어야 해요.');assert.equal(t.calls.filter(c=>c.method!=='GET').length,0);assert.equal(t.c.state().authority.version,1);}finally{t.c.dispose();setLanguagePreference('en');globalThis.localStorage=storage;}});
test('a permission confirmation cannot authorize a write after session loss',async()=>{let t;t=setup(undefined,{confirmChange:()=>{void t.c.syncProfile({authenticated:false,profile:null,busy:false});return true;}});try{await t.sync();field(t.host,'scope-world_item_gift').checked=true;await click(t,'grant');assert.equal(t.calls.filter(c=>c.method!=='GET').length,0);assert.equal(t.c.state().keys.length,0);assert.equal(t.c.state().entry.reason,'signed_out');}finally{t.c.dispose();}});

test('lost-response recovery identifies its exact key among multiple usable rows and revokes only after explicit selection',async()=>{const other={...K,id:'pak_22222222-2222-4222-8222-222222222222'},t=setup((u,i)=>i.method==='GET'?reply(status({keys:[other]})):i.method==='DELETE'?reply({key:{...K,revokedAt:1000}}):reply({status:'already_issued',row:K}),{},true);try{await t.sync();await click(t,'back');await click(t,'back');await click(t,'issue-key');assert.ok(all(t.host,n=>n.dataset.part==='connection-message')[0].textContent.includes(K.id));const count=t.calls.length;await click(t,'recover-key');assert.equal(t.calls.length,count);assert.equal(all(t.host,n=>n.className==='entry-advanced')[0].open,true);assert.equal(document.activeElement,action(t.host,'revoke-key-'+K.id));assert.equal(t.c.state().rawKeyVisible,false);await click(t,'revoke-key-'+K.id);assert.equal(t.calls.at(-1).url,'/api/personal/keys/'+K.id);assert.equal(t.calls.at(-1).method,'DELETE');assert.equal(t.c.state().keys.find(k=>k.id===other.id).revokedAt,null);assert.equal(t.calls.filter(c=>c.method==='POST').length,1);}finally{t.c.dispose();}});
